#[verus::spec]
fn lagval2d(x: Vec<f32>, y: Vec<f32>, c: Vec<Vec<f32>>) -> Vec<f32> {
    // Check that the input arrays have equal length and are non-empty
    let n = x.len();
    let m = y.len();
    // Requires: x and y must have the same positive length
    // Requires: c must be a non-empty grid with non-empty rows
    assert(n == m && n > 0);
    assert(!c.is_empty() && c.iter().all(|row| !row.is_empty()));

    // If the coefficient grid is 1x1, return an output array filled with that value
    if c.len() == 1 && c[0].len() == 1 {
        let value = c[0][0];
        // Ensures: The output vector has the same length as x and y, filled with the value from c
        let result = vec![value; n];
        assert(result.len() == n);
        return result;
    }

    // Otherwise, return an output array filled with zeros
    let result = vec![0.0; n];
    assert(result.len() == n);
    return result;
}

#[verus::spec]
fn default_value(c: &Vec<Vec<f32>>) -> f32 {
    // Requires: c must be a non-empty grid with non-empty rows
    assert(!c.is_empty() && !c[0].is_empty());
    // Ensures: Returns the first element of the coefficient grid
    let value = c[0][0];
    return value;
}

